def digit_sum(n: int) -> int:
    total = 0
    while n > 0:
        total += n % 10
        n //= 10
    return total

def to_binary(n: int) -> str:
    if n == 0:
        return '0'
    result = ''
    while n > 0:
        result = str(n & 1) + result
        n >>= 1
    return result

def to_binary(n: int) -> str:
    if n == 0:
        return '0'
    bits = []
    while n > 0:
        bits.append(str(n & 1))
        n >>= 1
    return ''.join(reversed(bits))

