def int_sqrt(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 0
    lo = 1
    hi = 1 << ((n.bit_length() + 1) // 2)
    while lo <= hi:
        mid = (lo + hi) // 2
        sq = mid * mid
        if sq == n:
            return mid
        elif sq < n:
            lo = mid + 1
        else:
            hi = mid - 1
    return hi

